3	     3	/// `TranscriptView`'s keys and clicks (spec §11 TX-21). It takes ← and →
4	     4	/// (one word, selected and sought, through `onActivate`), ↑ and ↓ (the word
5	     5	/// nearest in x on the adjacent laid-out line, the same), ⇧ with any of them
6	     6	/// (extend the selection, no seek), ⌘A (`selectAll(_:)`, which the nil-target
7	     7	/// Edit ▸ Select All reaches first), Esc (clear the selection, or pass the key
8	     8	/// up when there is none), and ⌫ and ⌦ with words selected (`deleteKey()`,
9	     9	/// TX3a, spec §11 TX-31: one "Delete Words"; Edit ▸ Delete's bare ⌫ reaches
10	    10	/// the editor's forward first). Since TX3b (TX-34) a click on a pause token
11	    11	/// selects it; Esc, ⌫ and ⌦ act on it, and the arrows move from the word
12	    12	/// before it. With nothing selected they pass up, and
13	    13	/// Return passes up unchanged until TX5. Every other key goes to
14	    14	/// `super.keyDown`, so J, K, L, I, O and M reach `handleEditorKey` as from the
15	    15	/// timeline; Space never arrives here (`SpaceKey.route` takes it at the
16	    16	/// window). A click makes the view first responder; a drag selects
17	    17	/// (`+Delete`). Every selection a person makes is told through `onSelect`.
18	    18	extension TranscriptView {
19	    19	
20	    20	    override func keyDown(with event: NSEvent) {
21	    21	        let flags = event.modifierFlags.intersection([.command, .option, .control, .shift])
22	    22	        guard let scalar = event.charactersIgnoringModifiers?.unicodeScalars.first?.value,
23	    23	            flags.isSubset(of: [.shift])
24	    24	        else {
25	    25	            super.keyDown(with: event)
26	    26	            return
27	    27	        }
28	    28	        let extend = flags.contains(.shift)
29	    29	        let held = selection != nil || pauseSelection != nil
30	    30	        switch scalar {
31	    31	        case UInt32(NSLeftArrowFunctionKey): step(by: -1, extend: extend)
32	    32	        case UInt32(NSRightArrowFunctionKey): step(by: 1, extend: extend)
33	    33	        case UInt32(NSUpArrowFunctionKey): line(up: true, extend: extend)
34	    34	        case UInt32(NSDownArrowFunctionKey): line(up: false, extend: extend)
35	    35	        case 27 where !extend && held: select(nil)
36	    36	        case 0x7F where !extend && held, UInt32(NSDeleteFunctionKey) where !extend && held:
37	    37	            deleteKey()
38	    38	        default: super.keyDown(with: event)
39	    39	        }
40	    40	    }
41	    41	
42	    42	    override func selectAll(_ sender: Any?) {
43	    43	        guard !tokenStarts.isEmpty else { return }
44	    44	        select(0...(tokenStarts.count - 1))
45	    45	    }
46	    46	
47	    47	    /// The token a key moves from: the selection's moving end, else the
48	    48	    /// word before a selected pause, else the highlighted word.
49	    49	    private var caret: Int? {
50	    50	        guard let selection else { return pauseSelection.map { pauses[$0].after } ?? highlighted }
51	    51	        if let anchor = selectionAnchor, anchor == selection.upperBound, anchor != selection.lowerBound {
52	    52	            return selection.lowerBound
53	    53	        }
54	    54	        return selection.upperBound
55	    55	    }
56	    56	
57	    57	    private func step(by delta: Int, extend: Bool) {
58	    58	        guard !tokenStarts.isEmpty else { return }
59	    59	        let from = caret ?? (delta > 0 ? -1 : tokenStarts.count)
60	    60	        move(to: min(max(from + delta, 0), tokenStarts.count - 1), extend: extend)
61	    61	    }
62	    62	
63	    63	    private func line(up: Bool, extend: Bool) {
64	    64	        guard let from = caret ?? (tokenStarts.isEmpty ? nil : 0),
65	    65	            let target = tokenOnAdjacentLine(to: from, up: up)
66	    66	        else {
67	    67	            NSSound.beep()
68	    68	            return
69	    69	        }
70	    70	        move(to: target, extend: extend)
71	    71	    }
72	    72	
73	    73	    /// Selects `index` and seeks there, or, extending, grows the selection
74	    74	    /// from its anchor without a seek.
75	    75	    private func move(to index: Int, extend: Bool) {
76	    76	        if extend {
77	    77	            let anchor = min(max(selectionAnchor ?? caret ?? index, 0), tokenStarts.count - 1)
78	    78	            setSelection(min(anchor, index)...max(anchor, index))
79	    79	            selectionAnchor = anchor
80	    80	            onSelect?(selection)
81	    81	        } else {
82	    82	            select(index...index)
83	    83	            onActivate?(index)
84	    84	        }
85	    85	        if let rect = rects(forToken: index).first, !visibleRect.contains(rect) {
86	    86	            scrollToVisible(rect.insetBy(dx: 0, dy: -24))
87	    87	            layoutViewport()
88	    88	        }
89	    89	    }
90	    90	
91	    91	    override func mouseDown(with event: NSEvent) {
92	    92	        window?.makeFirstResponder(self)
93	    93	        let point = convert(event.locationInWindow, from: nil)
94	    94	        if let paragraph = paragraphIndex(at: point) {
95	    95	            onParagraph?(paragraph)
96	    96	            return
97	    97	        }
98	    98	        if !event.modifierFlags.contains(.shift), let pause = pauseIndex(at: point) {
99	    99	            clickPause(pause)
100	   100	            return
101	   101	        }
102	   102	        guard let index = tokenIndex(at: point) else { return }
103	   103	        if event.modifierFlags.contains(.shift) {
104	   104	            move(to: index, extend: true)
105	   105	        } else {
106	   106	            click(token: index)
107	   107	        }
108	   108	    }
109	   109	
110	   110	    /// A plain click on token `index`: it alone selected, and sought. The
111	   111	    /// mouse's path, which `transcript_view`'s `click` takes too.
112	   112	    func click(token index: Int) {
113	   113	        select(index...index)
114	   114	        onActivate?(index)
115	   115	    }
116	   116	}
