119	     3	/// `TranscriptView`'s part in deleting words (road map "creator-jobs" TX3a,
120	     4	/// spec §11 TX-31): a drag selects from the word the press selected, ⌫ and ⌦
121	     5	/// with words selected ask the pane to delete them (`onDelete`), and the pane
122	     6	/// hands its widened selection back through `adopt`, which tells nobody.
123	     7	extension TranscriptView {
124	     8	
125	     9	    /// A drag from a selected word: the selection runs from its anchor to
126	    10	    /// the word under the pointer (the last word starting before it, between
127	    11	    /// words), told through `onSelect` whenever it changes.
128	    12	    override func mouseDragged(with event: NSEvent) {
129	    13	        guard let anchor = selectionAnchor, selection != nil, !tokenStarts.isEmpty else { return }
130	    14	        autoscroll(with: event)
131	    15	        let point = convert(event.locationInWindow, from: nil)
132	    16	        guard let offset = characterOffset(at: point) else { return }
133	    17	        let index = token(atOrBefore: offset) ?? 0
134	    18	        let range = min(anchor, index)...max(anchor, index)
135	    19	        guard range != selection else { return }
136	    20	        setSelection(range)
137	    21	        selectionAnchor = anchor
138	    22	        onSelect?(range)
139	    23	    }
140	    24	
141	    25	    /// ⌫ or ⌦ with words or a pause selected (TX-34).
142	    26	    func deleteKey() {
143	    27	        guard selection != nil || pauseSelection != nil else { return }
144	    28	        onDelete?()
145	    29	    }
146	    30	
147	    31	    /// The pane's widened selection, shown without telling `onSelect`; the
148	    32	    /// ⇧ anchor kept when it lies inside, else the selection's start.
149	    33	    func adopt(_ range: ClosedRange<Int>) {
150	    34	        guard range.lowerBound >= 0, range.upperBound < tokenStarts.count else { return }
151	    35	        let anchor = selectionAnchor.flatMap { range.contains($0) ? $0 : nil } ?? range.lowerBound
152	    36	        if range != selection { setSelection(range) }
153	    37	        selectionAnchor = anchor
154	    38	    }
155	    39	}
