158	     3	/// `TranscriptView`'s pause tokens (road map "creator-jobs" TX3b, spec §11
159	     4	/// TX-34): the hit test on a pause's text, a click on one — the word
160	     5	/// selection cleared, the pause selected and told through `onSelectPause` —
161	     6	/// and the selected pause's mark, drawn behind the text as a word
162	     7	/// selection's is.
163	     8	extension TranscriptView {
164	     9	
165	    10	    /// The pause whose text is under `point`.
166	    11	    func pauseIndex(at point: NSPoint) -> Int? {
167	    12	        guard !pauseRanges.isEmpty, let offset = characterOffset(at: point) else { return nil }
168	    13	        var low = 0
169	    14	        var high = pauseRanges.count
170	    15	        while low < high {
171	    16	            let mid = (low + high) / 2
172	    17	            if pauseRanges[mid].location <= offset { low = mid + 1 } else { high = mid }
173	    18	        }
174	    19	        for index in [low - 1, low] where pauseRanges.indices.contains(index) {
175	    20	            if rects(for: pauseRanges[index]).contains(where: { $0.insetBy(dx: -2, dy: 0).contains(point) }) {
176	    21	                return index
177	    22	            }
178	    23	        }
179	    24	        return nil
180	    25	    }
181	    26	
182	    27	    /// A click on pause `index`: the words' selection cleared, the pause
183	    28	    /// selected, and told. The mouse's path, which `transcript_view`'s
184	    29	    /// `select_pause` takes too.
185	    30	    func clickPause(_ index: Int) {
186	    31	        guard pauses.indices.contains(index) else { return }
187	    32	        selectionAnchor = nil
188	    33	        setSelection(nil)
189	    34	        setPauseSelection(index)
190	    35	        onSelectPause?(index)
191	    36	    }
192	    37	
193	    38	    /// The selected pause, behind its text.
194	    39	    func drawPauseMark(in dirtyRect: NSRect) {
195	    40	        guard let index = pauseSelection, pauseRanges.indices.contains(index) else { return }
196	    41	        DS.selectionFill.setFill()
197	    42	        for rect in rects(for: pauseRanges[index]) where rect.intersects(dirtyRect) {
198	    43	            rect.fill()
199	    44	        }
200	    45	    }
201	    46	}
