204	     3	/// What the Transcript tab asks of the editor (spec §11 TX-22): whether the
205	     4	/// transport plays, and a seek that leaves playback as it was; since TX3a
206	     5	/// (TX-31, TX-32) the document's in/out range, read and set through
207	     6	/// `set_range`'s door, the cut as one step named "Delete Words" or, since
208	     7	/// TX3b (TX-34), "Delete Pause" (true when it applied), and a refusal's beep
209	     8	/// and sentence.
210	     9	protocol TranscriptHost: AnyObject {
211	    10	    var transcriptIsPlaying: Bool { get }
212	    11	    func transcriptSeek(to time: Ticks)
213	    12	    var transcriptRange: TranscriptCut.Range? { get }
214	    13	    func transcriptSetRange(_ range: TranscriptCut.Range?)
215	    14	    @discardableResult func transcriptDelete(_ range: TranscriptCut.Range, name: String) -> Bool
216	    15	    func transcriptRefuse(_ sentence: String)
217	    16	}
