219	    18	/// The inspector's fifth tab (road map "creator-jobs" TX2a, spec §11 TX-20):
220	    19	/// the timeline's words in paragraphs (`TranscriptView`), under the tab's bar
221	    20	/// (`TranscriptBar`, TX2b, spec §11 TX-24) — Words from, Language, the status
222	    21	/// with Stop or Read, the same-speech notes and the clips with no words. The
223	    22	/// bar is built once in `init` and is the pane's one `makeHeader()` instance,
224	    23	/// so the controller pins it above the scroll view, as it does the Clip tab's
225	    24	/// header, and it never scrolls with the text.
226	    25	///
227	    26	/// `AssistantPane`'s shape: the view is built ONCE in `init`, never in
228	    27	/// `makeSections()`, and the pane is exactly the visible height (`== 0` at
229	    28	/// priority 1 under the controller's `>=`), so the transcript scrolls in its
230	    29	/// own `NSScrollView`. It reaches the editor only through `TranscriptHost`
231	    30	/// (`inspector.parent`) and the static table below, after
232	    31	/// `TimelineView+TrackMix`'s "static table keyed by the view", because
233	    32	/// `InspectorViewController.swift` and `EditorViewController.swift` are
234	    33	/// frozen. Whether it shows follows its superview, window and hidden state;
235	    34	/// shown, its source loads and wants (TX-22), hidden it releases.
236	    35	final class TranscriptPane: InspectorPaneView {
237	    36	    let transcriptView = TranscriptView(frame: NSRect(x: 0, y: 0, width: 280, height: 400))
238	    37	    private(set) var source: TranscriptTabSource!
239	    38	    private(set) var bar: TranscriptBar!
240	    39	    private let scroll = NSScrollView()
241	    40	    private weak var lastProject: ReelProject?
242	    41	    private var shownRebuilds = -1
243	    42	    /// The range the selection last set (TX-31); nil after a clear or a cut.
244	    43	    private var rangeSet: TranscriptCut.Range?
245	    44	
246	    45	    /// The pane each inspector made, weak to weak.
247	    46	    private static let table = NSMapTable<InspectorViewController, TranscriptPane>.weakToWeakObjects()
248	    47	
249	    48	    static func pane(in inspector: InspectorViewController) -> TranscriptPane? {
250	    49	        table.object(forKey: inspector)
251	    50	    }
252	    51	
253	    52	    override var tab: InspectorTab { .transcript }
254	    53	    override var emptyMessage: String? { nil }
255	    54	    override var structureSignature: String { "transcript" }
