258	    57	        super.init(inspector: inspector)
259	    58	        source = TranscriptTabSource(document: inspector.document) { [weak self] in
260	    59	            self?.sourceChanged()
261	    60	        }
262	    61	        bar = TranscriptBar(source: source)
263	    62	        Self.table.setObject(self, forKey: inspector)
264	    63	
265	    64	        scroll.translatesAutoresizingMaskIntoConstraints = false
266	    65	        scroll.hasVerticalScroller = true
267	    66	        scroll.autohidesScrollers = true
268	    67	        scroll.drawsBackground = false
269	    68	        scroll.borderType = .noBorder
270	    69	        transcriptView.autoresizingMask = [.width]
271	    70	        scroll.documentView = transcriptView
272	    71	        addSubview(scroll)
273	    72	        let collapse = heightAnchor.constraint(equalToConstant: 0)
274	    73	        collapse.priority = NSLayoutConstraint.Priority(1)
275	    74	        NSLayoutConstraint.activate([
276	    75	            scroll.topAnchor.constraint(equalTo: topAnchor),
277	    76	            scroll.leadingAnchor.constraint(equalTo: leadingAnchor),
278	    77	            scroll.trailingAnchor.constraint(equalTo: trailingAnchor),
279	    78	            scroll.bottomAnchor.constraint(equalTo: bottomAnchor),
280	    79	            collapse,
