282	    81	        transcriptView.onActivate = { [weak self] index in self?.seek(token: index) }
283	    82	        transcriptView.onParagraph = { [weak self] index in self?.seek(paragraph: index) }
284	    83	        transcriptView.onSelect = { [weak self] selection in self?.selectionChanged(selection) }
285	    84	        transcriptView.onDelete = { [weak self] in self?.deleteWords() }
286	    85	        transcriptView.onSelectPause = { [weak self] index in self?.pauseSelected(index) }
