415	   214	    /// A person's selection: widened, adopted, and its snapped cut made the
416	   215	    /// in/out range. A cleared selection clears the range only while it is
417	   216	    /// still the one the selection set.
418	   217	    func selectionChanged(_ selection: ClosedRange<Int>?) {
419	   218	        guard let host else { return }
420	   219	        guard let selection, let plan = plan(selection) else {
421	   220	            if rangeSet != nil, host.transcriptRange == rangeSet { host.transcriptSetRange(nil) }
422	   221	            rangeSet = nil
423	   222	            return
424	   223	        }
425	   224	        transcriptView.adopt(plan.selection)
426	   225	        let range = plan.range.end > plan.range.start ? plan.range : nil
427	   226	        host.transcriptSetRange(range)
428	   227	        rangeSet = range
429	   228	    }
