431	   230	    /// ⌫, ⌦, Edit ▸ Delete or Edit ▸ Ripple Delete with words selected:
432	   231	    /// planned again, refused in TX-32's order, else one "Delete Words"; with
433	   232	    /// a pause selected, `deletePause`.
434	   233	    func deleteWords() {
435	   234	        if let index = transcriptView.pauseSelection {
436	   235	            deletePause(index)
437	   236	            return
438	   237	        }
439	   238	        guard let host, let selection = transcriptView.selection, let plan = plan(selection) else {
440	   239	            NSSound.beep()
441	   240	            return
442	   241	        }
443	   242	        transcriptView.adopt(plan.selection)
444	   243	        if let refusal = plan.refusal {
445	   244	            host.transcriptRefuse(refusal.sentence)
446	   245	            return
447	   246	        }
448	   247	        guard plan.range.end > plan.range.start else {
449	   248	            NSSound.beep()
450	   249	            return
451	   250	        }
452	   251	        // Cleared first, so the rebuild the cut causes does not re-plan.
453	   252	        let held = rangeSet
454	   253	        rangeSet = nil
455	   254	        if !host.transcriptDelete(plan.range, name: "Delete Words") { rangeSet = held }
456	   255	    }
