333	   333	    override func draw(_ dirtyRect: NSRect) {
334	   334	        guard let context = NSGraphicsContext.current?.cgContext else { return }
335	   335	        drawMarks(in: dirtyRect)
336	   336	        // Walked from the fragment at the dirty top rather than read from
337	   337	        // `fragments`: a layout elsewhere (a far highlight's rects) can move
338	   338	        // the fragments in sight after the viewport's last pass.
339	   339	        let top = CGPoint(x: 0, y: max(dirtyRect.minY - Self.inset.height, 0))
340	   340	        guard let start = layoutManager.textLayoutFragment(for: top)?.rangeInElement.location
341	   341	            ?? fragments.first?.rangeInElement.location
342	   342	        else { return }
343	   343	        layoutManager.enumerateTextLayoutFragments(from: start, options: [.ensuresLayout]) {
344	   344	            fragment in
345	   345	            let frame = fragment.layoutFragmentFrame.offsetBy(
346	   346	                dx: Self.inset.width, dy: Self.inset.height)
347	   347	            guard frame.minY <= dirtyRect.maxY else { return false }
348	   348	            if frame.intersects(dirtyRect) { fragment.draw(at: frame.origin, in: context) }
349	   349	            return true
350	   350	        }
351	   351	    }
