414	     3	/// The timeline transcript (road map "creator-jobs" TX1, spec §11 TX-10,
415	     4	/// TX-13): every heard word of the edited container in timeline order,
416	     5	/// nested instances included, each with its clip, track, editability and a
417	     6	/// stable identity. Pure: it is handed the plan, the snapshot and each
418	     7	/// media's source words, and reads no file, no cache and no window.
419	     8	///
420	     9	/// - `read` finds the INSTANCES — the plan's audio segments, each through
421	    10	///   `Transcriber.jobs`' gate on its inner clip and the envelope's
422	    11	///   `SilenceDetector.isAudible` — and the clips the gate refuses, found by
423	    12	///   walking the clips rather than the segments (the core places no segment
424	    13	///   for a clip with its audio off).
425	    14	/// - `words` places each media's source words in each instance by R6-10's
426	    15	///   mapping, orders them (start, end, front track first, source order),
427	    16	///   counts their identities and asks `TimelineTranscript+Rules.swift`
428	    17	///   whether each may be cut (TX-11).
429	    18	/// - `window`, `overlapping`, `page` and `frameFloor` are TX-13's window and
430	    19	///   paging.
431	    20	enum TimelineTranscript {
432	    21	
433	    22	    /// A word's identity (TX-10): the enclosing nest clip ids, the media, the
434	    23	    /// word's SOURCE start tick and k, the earlier words sharing the other
435	    24	    /// three. The inner clip's id is left out: a ripple gives every split's
436	    25	    /// second half a fresh id.
437	    26	    struct Identity: Hashable {
438	    27	        let nestPath: [UInt32]
439	    28	        let media: UInt32
440	    29	        let source: Ticks
441	    30	        let k: Int
442	    31	    }
443	    32	
444	    33	    /// One word of a media, in its SOURCE ticks. An on-device word's
445	    34	    /// `source` is its MOVED start (TX-15); `recognisedStart` is the
446	    35	    /// recogniser's own when TX-15 moved it.
447	    36	    struct SourceWord: Equatable {
448	    37	        let text: String
449	    38	        let source: Ticks
450	    39	        let sourceEnd: Ticks
451	    40	        let speaker: String?
452	    41	        var recognisedStart: Ticks? = nil
453	    42	
454	    43	        /// The tick an identity, a cut's match and a pause set key by
455	    44	        /// (TX-17): the recogniser's start, moved or not.
456	    45	        var identityTick: Ticks { recognisedStart ?? source }
457	    46	    }
458	    47	
459	    48	    /// A heard media's words and where they came from.
460	    49	    struct MediaWords: Equatable {
461	    50	        let media: UInt32
462	    51	        let engine: TranscriptionEngine
463	    52	        let language: String?
464	    53	        let fillersReported: Bool
465	    54	        let words: [SourceWord]
466	    55	        /// An on-device media read with no voice cache: its starts are the
467	    56	        /// recogniser's, unmoved (TX-18).
468	    57	        var voiceCacheMissing: Bool = false
