674	   263	    /// Why a window names no part of the timeline.
675	   264	    enum WindowError: LocalizedError, Equatable {
676	   265	        case outside(from: Ticks?, to: Ticks?, duration: Ticks)
677	   266	
678	   267	        var errorDescription: String? {
679	   268	            switch self {
680	   269	            case .outside(let from, let to, let duration):
681	   270	                let bounds = [from.map { "from \($0)" }, to.map { "to \($0)" }]
682	   271	                    .compactMap { $0 }.joined(separator: " ")
683	   272	                return "The window \(bounds) is outside the timeline, which runs from 0 to "
684	   273	                    + "\(duration) ticks."
685	   274	            }
686	   275	        }
687	   276	    }
688	   277	
689	   278	    /// TR-13's window over the container: nil with neither bound; `to` not
690	   279	    /// after `from` refused as TR-13's `.empty`; clamped to [0, duration);
691	   280	    /// nothing left refused as `.outside`.
692	   281	    static func window(from: Ticks?, to: Ticks?, duration: Ticks) throws -> TranscriptReader.Window? {
693	   282	        guard from != nil || to != nil else { return nil }
694	   283	        if let from, let to, to <= from {
695	   284	            throw TranscriptReader.WindowError.empty(from: from, to: to)
696	   285	        }
697	   286	        let lower = max(from ?? 0, 0)
698	   287	        let upper = min(to ?? duration, duration)
699	   288	        guard lower < upper else {
700	   289	            throw WindowError.outside(from: from, to: to, duration: duration)
701	   290	        }
702	   291	        return TranscriptReader.Window(from: lower, to: upper)
703	   292	    }
704	   293	
705	   294	    /// TR-13's overlap rule: a word across an edge is kept whole; a word with
706	   295	    /// no length belongs when from <= its start < to.
707	   296	    static func overlapping(_ words: [Word], in window: TranscriptReader.Window) -> [Word] {
708	   297	        words.filter { $0.start < window.to && max($0.end, $0.start + 1) > window.from }
709	   298	    }
710	   299	
711	   300	    /// The largest frame boundary at or before `t`, on the canvas's grid
712	   301	    /// through `ReelTime.snapToFrame` — so the nearest-frame snap of a
713	   302	    /// `from` returns it unchanged.
714	   303	    static func frameFloor(_ t: Ticks, fps: Fps) -> Ticks {
715	   304	        let nearest = ReelTime.snapToFrame(t, fps: fps)
716	   305	        guard nearest > t else { return nearest }
717	   306	        return ReelTime.snapToFrame(nearest - max(1, fps.frameDuration), fps: fps)
718	   307	    }
719	   308	
720	   309	    /// One page of `words` (already windowed): all of them when they fit;
721	   310	    /// else the first `pageLimit`, cut back until the next word's frame
722	   311	    /// floor is past the last kept word's, and `nextFrom` that floor. A cut
723	   312	    /// that would empty the page keeps it whole, and `nextFrom` is then the
724	   313	    /// frame boundary after its last word's frame.
725	   314	    static func page(_ words: [Word], fps: Fps) -> (words: [Word], nextFrom: Ticks?) {
726	   315	        guard words.count > pageLimit else { return (words, nil) }
727	   316	        var count = pageLimit
728	   317	        while count > 0,
729	   318	            frameFloor(words[count].start, fps: fps) <= frameFloor(words[count - 1].start, fps: fps)
730	   319	        {
731	   320	            count -= 1
732	   321	        }
733	   322	        if count == 0 {
734	   323	            let last = frameFloor(words[pageLimit - 1].start, fps: fps)
735	   324	            let next = ReelTime.snapToFrame(last + max(1, fps.frameDuration), fps: fps)
736	   325	            return (Array(words.prefix(pageLimit)), next)
737	   326	        }
738	   327	        return (Array(words.prefix(count)), frameFloor(words[count].start, fps: fps))
739	   328	    }
