93	    93	    /// Lays `tokens` out, keeping the top visible token's identity at its
94	    94	    /// offset from the visible top, else the nearest later start; with them
95	    95	    /// `pauses` (TX-34), a selected pause re-mapped by the identities of the
96	    96	    /// tokens on its two sides.
97	    97	    func show(
98	    98	        _ tokens: TranscriptTokens, pauses: [TranscriptCut.Pause] = [], fps: Fps, timecodeFrames: Bool
99	    99	    ) {
100	   100	        let anchor = topVisibleToken().map { index -> (TimelineTranscript.Identity, Ticks, CGFloat) in
101	   101	            let token = model.tokens[index]
102	   102	            let y = (rects(forToken: index).first?.minY ?? visibleRect.minY) - visibleRect.minY
103	   103	            return (token.word.id, token.word.start, y)
104	   104	        }
105	   105	        let selected = selection.map { (model.tokens[$0.lowerBound].word.id, model.tokens[$0.upperBound].word.id) }
106	   106	        let lit = highlighted.map { model.tokens[$0].word.id }
107	   107	        let anchored = selectionAnchor.flatMap { model.tokens.indices.contains($0) ? model.tokens[$0].word.id : nil }
108	   108	        let pausedBetween = pauseSelection.flatMap { index -> (TimelineTranscript.Identity, TimelineTranscript.Identity)? in
109	   109	            let after = self.pauses[index].after
110	   110	            guard after + 1 < model.tokens.count else { return nil }
111	   111	            return (model.tokens[after].word.id, model.tokens[after + 1].word.id)
112	   112	        }
113	   113	        model = tokens
114	   114	        self.pauses = pauses.filter { $0.after + 1 < tokens.tokens.count }
115	   115	        shownStyle = (fps, timecodeFrames)
116	   116	        contentStorage.textStorage?.setAttributedString(text(fps: fps, frames: timecodeFrames))
117	   117	        highlighted = lit.flatMap { model.index(of: $0) }
118	   118	        selection = selected.flatMap { pair in
119	   119	            guard let low = model.index(of: pair.0), let high = model.index(of: pair.1), low <= high
120	   120	            else { return nil }
121	   121	            return low...high
122	   122	        }
123	   123	        pauseSelection = pausedBetween.flatMap { pair in
124	   124	            self.pauses.firstIndex {
125	   125	                model.tokens[$0.after].word.id == pair.0 && model.tokens[$0.after + 1].word.id == pair.1
126	   126	            }
127	   127	        }
128	   128	        // The ⇧-extension's anchor follows its word, else the selection's
129	   129	        // start: an old index can lie past a shrunk text.
130	   130	        selectionAnchor = selection.map { range in
131	   131	            anchored.flatMap { model.index(of: $0) }.flatMap { range.contains($0) ? $0 : nil } ?? range.lowerBound
132	   132	        }
133	   133	        fitContainer()
134	   134	        layoutViewport()
135	   135	        if let (id, start, offset) = anchor,
136	   136	            let index = model.index(of: id) ?? model.firstIndex(atOrAfter: start),
137	   137	            let rect = rects(forToken: index).first
138	   138	        {
139	   139	            scroll(to: rect.minY - offset)
140	   140	        }
141	   141	        needsDisplay = true
142	   142	    }
