543	   132	    /// container's clips, then recursively every shown nest's, each clip
544	   133	    /// once, its first path kept.
545	   134	    static func walk(_ snapshot: ProjectSnapshot)
546	   135	        -> [(clip: ClipSnapshot, nestPath: [UInt32], nest: NestSnapshot?)]
547	   136	    {
548	   137	        var out: [(clip: ClipSnapshot, nestPath: [UInt32], nest: NestSnapshot?)] = []
549	   138	        var seen = Set<UInt32>()
550	   139	        func visit(_ clips: [ClipSnapshot], path: [UInt32], nest: NestSnapshot?, open: [UInt32]) {
551	   140	            for clip in clips.sorted(by: { ($0.start, $0.id) < ($1.start, $1.id) }) {
552	   141	                if seen.insert(clip.id).inserted { out.append((clip, path, nest)) }
553	   142	                guard let inner = snapshot.nest(for: clip), !open.contains(inner.id) else {
554	   143	                    continue
555	   144	                }
556	   145	                visit(inner.clips, path: path + [clip.id], nest: inner, open: open + [inner.id])
557	   146	            }
558	   147	        }
559	   148	        visit(snapshot.clips, path: [], nest: nil, open: [])
560	   149	        return out
561	   150	    }
