563	   152	    /// The instances the plan's audio segments make, and every media clip
564	   153	    /// the gate refuses (TX-10). `maps` answers a clip's source map given
565	   154	    /// the nest clip ids leading to it.
566	   155	    static func read(
567	   156	        plan: CompositionPlan, snapshot: ProjectSnapshot, urls: [UInt32: URL],
568	   157	        maps: (_ clip: UInt32, _ nestPath: [UInt32]) -> SourceMap?
569	   158	    ) -> (instances: [Instance], noWords: [NoWords]) {
570	   159	        let walked = walk(snapshot)
571	   160	        var noWords: [NoWords] = []
572	   161	        var clips: [UInt32: ClipSnapshot] = [:]
573	   162	        for entry in walked {
574	   163	            clips[entry.clip.id] = entry.clip
575	   164	            guard case .media = entry.clip.source else { continue }
576	   165	            let path = entry.nestPath
577	   166	            let gate = Transcriber.jobs(
578	   167	                for: [entry.clip], in: snapshot, urls: urls, maps: { maps($0, path) })
579	   168	            guard gate.jobs.isEmpty, let problem = gate.problems.first else { continue }
580	   169	            let tag = entry.nest.map {
581	   170	                "clip \(entry.clip.id) in nest \($0.name.isEmpty ? "\($0.id)" : $0.name)"
582	   171	            } ?? "clip \(entry.clip.id)"
583	   172	            noWords.append(
584	   173	                NoWords(clip: entry.clip.id, nestPath: path, tag: tag, reason: problem.reason))
585	   174	        }
586	   175	        var instances: [Instance] = []
587	   176	        for track in plan.audioTracks {
588	   177	            for segment in track.segments where segment.duration > 0 {
589	   178	                guard let clip = clips[segment.clip], case .media = clip.source else { continue }
590	   179	                let nestPath = Array(segment.path.dropLast())
591	   180	                let gate = Transcriber.jobs(
592	   181	                    for: [clip], in: snapshot, urls: urls, maps: { maps($0, nestPath) })
593	   182	                guard let job = gate.jobs.first else { continue }
594	   183	                let span = (segment.start, segment.start + segment.duration)
595	   184	                guard SilenceDetector.isAudible(track.ramps, over: span) else { continue }
596	   185	                let container = track.track ?? clip.track
597	   186	                instances.append(
598	   187	                    Instance(
599	   188	                        segment: segment, clip: clip, job: job, track: container,
600	   189	                        trackIndex: snapshot.trackIndex(of: container) ?? -1))
601	   190	            }
602	   191	        }
603	   192	        return (instances, noWords)
604	   193	    }
