610	   199	    static func words(
611	   200	        _ instances: [Instance], media: [UInt32: MediaWords], snapshot: ProjectSnapshot
612	   201	    ) -> [Word] {
613	   202	        struct Placed {
614	   203	            let start: Ticks
615	   204	            let end: Ticks
616	   205	            let trackIndex: Int
617	   206	            let order: Int
618	   207	            let instance: Int
619	   208	            let source: SourceWord
620	   209	            let mediaWords: MediaWords
621	   210	        }
622	   211	        var placed: [Placed] = []
623	   212	        for (number, instance) in instances.enumerated() {
624	   213	            guard let heard = media[instance.job.media] else { continue }
625	   214	            let job = instance.job
626	   215	            let windowEnd = job.sourceIn + job.sourceLength
627	   216	            let segmentStart = instance.segment.start
628	   217	            let segmentEnd = segmentStart + instance.segment.duration
629	   218	            let shift = instance.segment.origin.map { $0 - instance.clip.start }
630	   219	            for (order, word) in heard.words.enumerated() {
631	   220	                guard word.source >= job.sourceIn, word.source < windowEnd else { continue }
632	   221	                var start = MediaTranscript.project(word.source, in: job)
633	   222	                var end = MediaTranscript.project(max(word.source, word.sourceEnd), in: job)
634	   223	                if let shift {
635	   224	                    start += shift
636	   225	                    end += shift
637	   226	                    guard start >= segmentStart, start < segmentEnd else { continue }
638	   227	                }
639	   228	                placed.append(
640	   229	                    Placed(
641	   230	                        start: start, end: end, trackIndex: instance.trackIndex, order: order,
642	   231	                        instance: number, source: word, mediaWords: heard))
643	   232	            }
644	   233	        }
645	   234	        placed.sort {
646	   235	            ($0.start, $0.end, -$0.trackIndex, $0.order, $0.instance)
647	   236	                < ($1.start, $1.end, -$1.trackIndex, $1.order, $1.instance)
648	   237	        }
649	   238	        let walls = SilenceDetector.overlapWalls(snapshot)
650	   239	        var counts: [Identity: Int] = [:]
651	   240	        return placed.map { p in
652	   241	            let instance = instances[p.instance]
653	   242	            let nestPath = Array(instance.segment.path.dropLast())
654	   243	            let key = Identity(
655	   244	                nestPath: nestPath, media: instance.job.media, source: p.source.identityTick, k: 0)
656	   245	            let k = counts[key, default: 0]
657	   246	            counts[key] = k + 1
658	   247	            let why = whyNotEditable(
659	   248	                start: p.start, end: p.end, nestPath: nestPath, track: instance.track,
660	   249	                snapshot: snapshot, walls: walls)
661	   250	            return Word(
662	   251	                text: p.source.text, start: p.start, end: p.end, clip: instance.clip.id,
663	   252	                track: instance.track, media: instance.job.media, engine: p.mediaWords.engine,
664	   253	                filler: FillerWords.isFiller(p.source.text), speaker: p.source.speaker,
665	   254	                editable: why == nil, why: why,
666	   255	                id: Identity(
667	   256	                    nestPath: nestPath, media: instance.job.media, source: p.source.identityTick,
668	   257	                    k: k))
669	   258	        }
670	   259	    }
